package fr.bbodin.courbedepoids;
import android.app.AlertDialog;import android.app.Fragment;import android.app.TimePickerDialog;import android.graphics.Color;import android.os.Bundle;import android.text.InputType;import android.view.Gravity;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.EditText;import android.widget.ImageView;import android.widget.LinearLayout;import android.widget.RadioButton;import android.widget.RadioGroup;import android.widget.TextView;import android.widget.Toast;import java.text.SimpleDateFormat;import java.util.ArrayList;import java.util.Calendar;import java.util.Collections;import java.util.List;import java.util.Locale;import java.util.TimeZone;
public class HistoryFragment extends Fragment{
 private LinearLayout list;private WeightDatabase db;private ImageView filterWeight,filterWater,filterSport;private boolean showWeight=true,showWater=true,showSport=true;private final SimpleDateFormat tf=new SimpleDateFormat("HH:mm",Locale.FRANCE);private LoggingTypeRegistry registry;private final java.util.Set<String> hiddenCategories=new java.util.HashSet<>(),hiddenTypes=new java.util.HashSet<>();
 private static class Entry{final WeightDatabase.GenericEvent g;final String date;final long time;Entry(WeightDatabase.GenericEvent e){g=e;date=e.date;time=e.createdAt;}}
 @Override public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){return i.inflate(R.layout.activity_history,c,false);}
 @Override public void onViewCreated(View v,Bundle b){super.onViewCreated(v,b);db=new WeightDatabase(getActivity());registry=new LoggingTypeRegistry(getActivity());list=v.findViewById(R.id.history_list);LinearLayout f=new LinearLayout(getActivity());f.setOrientation(LinearLayout.HORIZONTAL);f.setGravity(Gravity.CENTER_VERTICAL);f.setPadding(dp(19),dp(8),dp(19),dp(8));filterWeight=filter(R.drawable.ic_scale,"Afficher ou masquer les mesures de poids");filterWater=filter(R.drawable.ic_water,"Afficher ou masquer les mesures d’eau");filterSport=filter(R.drawable.ic_sport,"Afficher ou masquer les mesures de sport");LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,dp(60),1);wp.setMargins(dp(3),0,dp(3),0);f.addView(filterWeight,wp);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,dp(60),1);ap.setMargins(dp(3),0,dp(3),0);f.addView(filterWater,ap);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,dp(60),1);sp.setMargins(dp(3),0,dp(3),0);f.addView(filterSport,sp);((ViewGroup)v).addView(f,1,new ViewGroup.LayoutParams(-1,-2));f.setVisibility(View.GONE);filterWeight.setOnClickListener(x->{showWeight=!showWeight;styleFilter(filterWeight,showWeight);render();});filterWater.setOnClickListener(x->{showWater=!showWater;styleFilter(filterWater,showWater);render();});filterSport.setOnClickListener(x->{showSport=!showSport;styleFilter(filterSport,showSport);render();});styleFilter(filterWeight,showWeight);styleFilter(filterWater,showWater);styleFilter(filterSport,showSport);addConfiguredFilters((ViewGroup)v);render();}
 private void addConfiguredFilters(ViewGroup root){
  java.util.LinkedHashMap<String,java.util.List<org.json.JSONObject>> categories=new java.util.LinkedHashMap<>();
  for(org.json.JSONObject type:registry.getTypes()){String category=type.optString("category","other");if(!categories.containsKey(category))categories.put(category,new java.util.ArrayList<>());categories.get(category).add(type);}
  LinearLayout categoryRow=new LinearLayout(getActivity());categoryRow.setOrientation(LinearLayout.HORIZONTAL);categoryRow.setPadding(dp(16),dp(4),dp(16),dp(4));
  android.widget.HorizontalScrollView categoryScroll=new android.widget.HorizontalScrollView(getActivity());categoryScroll.setHorizontalScrollBarEnabled(false);categoryScroll.addView(categoryRow);
  for(String category:categories.keySet()){TextView chip=filterChip(categoryLabel(category));chip.setOnClickListener(v->{if(hiddenCategories.contains(category))hiddenCategories.remove(category);else hiddenCategories.add(category);styleChip(chip,!hiddenCategories.contains(category));render();});styleChip(chip,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(42));p.setMargins(0,0,dp(8),0);categoryRow.addView(chip,p);}
  LinearLayout typeRow=new LinearLayout(getActivity());typeRow.setOrientation(LinearLayout.HORIZONTAL);typeRow.setPadding(dp(16),dp(2),dp(16),dp(8));
  android.widget.HorizontalScrollView typeScroll=new android.widget.HorizontalScrollView(getActivity());typeScroll.setHorizontalScrollBarEnabled(false);typeScroll.addView(typeRow);
  for(org.json.JSONObject type:registry.getTypes()){String id=type.optString("id");TextView chip=filterChip(type.optString("icon","•")+" "+type.optString("label",id));chip.setContentDescription("Filtrer "+type.optString("label",id));chip.setOnClickListener(v->{if(hiddenTypes.contains(id))hiddenTypes.remove(id);else hiddenTypes.add(id);styleChip(chip,!hiddenTypes.contains(id));render();});styleChip(chip,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(42));p.setMargins(0,0,dp(8),0);typeRow.addView(chip,p);}
  root.addView(categoryScroll,2,new ViewGroup.LayoutParams(-1,-2));root.addView(typeScroll,3,new ViewGroup.LayoutParams(-1,-2));
 }
 private TextView filterChip(String label){TextView chip=new TextView(getActivity());chip.setText(label);chip.setTextSize(13);chip.setGravity(Gravity.CENTER);chip.setPadding(dp(12),0,dp(12),0);chip.setBackgroundResource(R.drawable.bg_input);chip.setClickable(true);chip.setFocusable(true);return chip;}
 private void styleChip(TextView chip,boolean selected){chip.setBackgroundResource(selected?R.drawable.bg_primary_button:R.drawable.bg_input);chip.setTextColor(selected?Color.WHITE:Color.rgb(20,123,239));}
 private String categoryLabel(String category){if("health".equals(category))return "Santé";if("nutrition".equals(category))return "Nutrition";if("activity".equals(category))return "Activité";if("body".equals(category))return "Corps";return category;}
 private boolean isGenericVisible(WeightDatabase.GenericEvent event){org.json.JSONObject type=registry.getType(event.typeId);String category=type==null?"other":type.optString("category","other");return !hiddenCategories.contains(category)&&!hiddenTypes.contains(event.typeId);}
 private ImageView filter(int icon,String description){ImageView v=new ImageView(getActivity());v.setImageResource(icon);v.setContentDescription(description);v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setClickable(true);v.setFocusable(true);return v;}
 private void styleFilter(ImageView view,boolean selected){view.setAlpha(1f);view.setBackgroundResource(selected?R.drawable.bg_primary_button:R.drawable.bg_input);view.setColorFilter(selected?Color.WHITE:Color.rgb(20,123,239));}
 @Override public void onResume(){super.onResume();if(db!=null&&list!=null)render();}
 private void render(){list.removeAllViews();List<Entry> es=new ArrayList<>();for(WeightDatabase.GenericEvent x:db.allGenericEvents())if(isGenericVisible(x))es.add(new Entry(x));Collections.sort(es,(a,b)->{int n=b.date.compareTo(a.date);return n!=0?n:Long.compare(b.time,a.time);});String day=null;for(Entry e:es){if(!e.date.equals(day)){day=e.date;TextView h=new TextView(getActivity());h.setText(dateLabel(day));h.setTextSize(16);h.setTypeface(null,android.graphics.Typeface.BOLD);h.setTextColor(Color.rgb(20,36,58));h.setPadding(dp(4),dp(16),dp(4),dp(8));list.addView(h);}addRow(e);}if(es.isEmpty()){TextView t=new TextView(getActivity());t.setText("Aucune mesure pour les catégories sélectionnées.");t.setTextSize(16);t.setTextColor(Color.rgb(100,116,139));t.setGravity(Gravity.CENTER);t.setPadding(dp(12),dp(48),dp(12),0);list.addView(t);}}
 private void addRow(Entry e){LinearLayout row=new LinearLayout(getActivity());row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(12),dp(14),dp(12));row.setBackgroundResource(R.drawable.bg_card);row.setOnClickListener(v->editGeneric(e.g));row.setOnLongClickListener(v->{confirmDelete(e);return true;});org.json.JSONObject type=registry.getType(e.g.typeId);TextView icon=new TextView(getActivity());icon.setText(type==null?"•":type.optString("icon","•"));icon.setTextSize(24);icon.setGravity(Gravity.CENTER);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(36),dp(36));ip.setMarginEnd(dp(12));row.addView(icon,ip);LinearLayout info=new LinearLayout(getActivity());info.setOrientation(LinearLayout.VERTICAL);info.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));String label=type==null?e.g.typeId:type.optString("label",e.g.typeId);TextView title=new TextView(getActivity());title.setText(label+" · "+formatPayload(type,e.g.payload));title.setTextSize(15);title.setTextColor(Color.rgb(71,85,105));info.addView(title);TextView time=new TextView(getActivity());time.setText("Mesuré à "+tf.format(new java.util.Date(e.time))+" · "+TimeZone.getDefault().getID());time.setTextSize(12);time.setTextColor(Color.rgb(100,116,139));info.addView(time);row.addView(info);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(7);list.addView(row,p);}
 private String formatPayload(org.json.JSONObject type,String raw){StringBuilder out=new StringBuilder();try{org.json.JSONObject payload=new org.json.JSONObject(raw);org.json.JSONArray fields=type==null?null:type.optJSONArray("fields");java.util.HashSet<String> used=new java.util.HashSet<>();if(fields!=null){for(int i=0;i<fields.length();i++){org.json.JSONObject f=fields.optJSONObject(i);if(f==null)continue;String id=f.optString("id");if(!payload.has(id)||payload.isNull(id))continue;Object value=payload.opt(id);if(value==null||String.valueOf(value).trim().isEmpty())continue;if(out.length()>0)out.append(" · ");out.append(f.optString("label",id)).append(": ").append(value);used.add(id);}}java.util.Iterator<String> it=payload.keys();while(it.hasNext()){String id=it.next();if(used.contains(id))continue;Object value=payload.opt(id);if(value==null||String.valueOf(value).trim().isEmpty())continue;if(out.length()>0)out.append(" · ");out.append(id).append(": ").append(value);}}catch(Exception ignored){}return out.length()==0?"Aucun détail":out.toString();}
 private void editGeneric(WeightDatabase.GenericEvent event){org.json.JSONObject type=registry.getType(event.typeId);if(type==null){new AlertDialog.Builder(getActivity()).setTitle(event.typeId).setMessage(event.payload).setPositiveButton("Fermer",null).show();return;}org.json.JSONObject values;try{values=new org.json.JSONObject(event.payload);}catch(Exception ex){values=new org.json.JSONObject();}ConfiguredLoggingForm configured=new ConfiguredLoggingForm(getActivity(),type,values);Calendar c=at(event.createdAt);LinearLayout wrapper=form();wrapper.addView(configured.getView(),new LinearLayout.LayoutParams(-1,dp(360)));timePicker(wrapper,c);new AlertDialog.Builder(getActivity()).setTitle("Modifier · "+type.optString("label",event.typeId)).setView(wrapper).setPositiveButton("Enregistrer",(dialog,which)->{try{org.json.JSONObject payload=configured.readPayload();String date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime());db.updateGenericEvent(event.id,event.typeId,date,c.getTimeInMillis(),payload.toString());render();Toast.makeText(getActivity(),"Entrée mise à jour.",Toast.LENGTH_SHORT).show();}catch(Exception ex){Toast.makeText(getActivity(),ex.getMessage()==null?"Données invalides":ex.getMessage(),Toast.LENGTH_LONG).show();}}).setNegativeButton("Annuler",null).show();}
 private void confirmDelete(Entry e){org.json.JSONObject type=registry.getType(e.g.typeId);String label=type==null?e.g.typeId:type.optString("label",e.g.typeId);new AlertDialog.Builder(getActivity()).setTitle("Supprimer « "+label+" » ?").setMessage("Cette action est définitive.").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(dialog,which)->{db.deleteEvent(e.g.typeId,String.valueOf(e.g.id));render();Toast.makeText(getActivity(),"Entrée supprimée.",Toast.LENGTH_SHORT).show();}).show();}
 private LinearLayout form(){LinearLayout f=new LinearLayout(getActivity());f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(20),dp(8),dp(20),0);return f;}
 private void timePicker(LinearLayout f,Calendar c){TextView t=new TextView(getActivity());t.setTextSize(16);t.setTextColor(Color.rgb(20,36,58));t.setPadding(0,dp(12),0,dp(12));Runnable update=()->t.setText("Heure · "+tf.format(c.getTime())+" ("+TimeZone.getDefault().getID()+")");update.run();t.setOnClickListener(v->new TimePickerDialog(getActivity(),(p,h,m)->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,m);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);update.run();},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show());f.addView(t);}
 private Calendar at(long t){Calendar c=Calendar.getInstance();c.setTimeInMillis(t);return c;}
 private String dateLabel(String raw){try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setTimeZone(TimeZone.getDefault());return new SimpleDateFormat("EEEE d MMMM yyyy",Locale.FRANCE).format(f.parse(raw));}catch(Exception e){return raw;}}
 private String water(int ml){return ml>=1000&&ml%1000==0?ml/1000+" L ("+ml+" ml)":ml+" ml";}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}